package com.example.agendapersonal.ui;
import android.app.Activity;import android.content.Intent;import android.os.Bundle;import android.view.View;import android.widget.*;
import com.example.agendapersonal.R;import com.example.agendapersonal.model.*;import com.example.agendapersonal.repository.*;import com.example.agendapersonal.util.ReglasAgenda;
import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;

/** Calendario compartido: las tareas aparecen solamente al inicio y al vencimiento. */
public class AgendaActivity extends com.example.agendapersonal.ui.ActividadTematica {
 private java.util.List<com.example.agendapersonal.ui.registro.Registro> virtuales=new ArrayList<>();private MenuNavegacion menu;private TareaRepository tareasRepo;private EventoRepository eventosRepo;
 private YearMonth mes=YearMonth.now();private LocalDate dia=LocalDate.now();private List<Tarea> tareas;private List<Evento> eventos;
 @Override protected void onCreate(Bundle b){super.onCreate(b);if(b!=null){mes=YearMonth.parse(b.getString("mes",mes.toString()));dia=LocalDate.parse(b.getString("dia",dia.toString()));}String device=getSharedPreferences("agenda_identidad",MODE_PRIVATE).getString("device_id",null);if(device==null){device=UUID.randomUUID().toString();getSharedPreferences("agenda_identidad",MODE_PRIVATE).edit().putString("device_id",device).apply();}tareasRepo=new TareaRepository(this,device);eventosRepo=new EventoRepository(this,device);menu=new MenuNavegacion(this);setContentView(menu.getRaiz());menu.establecerContenido(R.layout.activity_agenda);findViewById(R.id.botonMenu).setOnClickListener(v->menu.alternar());findViewById(R.id.mesAnterior).setOnClickListener(v->{mes=mes.minusMonths(1);calendario();});findViewById(R.id.mesSiguiente).setOnClickListener(v->{mes=mes.plusMonths(1);calendario();});findViewById(R.id.irHoy).setOnClickListener(v->{dia=LocalDate.now();mes=YearMonth.from(dia);calendario();listado();});findViewById(R.id.nuevaTareaAgenda).setOnClickListener(v->nuevo(TareasActivity.class));findViewById(R.id.nuevoEventoAgenda).setOnClickListener(v->nuevo(EventosActivity.class));}
 @Override protected void onResume(){super.onResume();try{tareas=tareasRepo.obtenerTodas();eventos=eventosRepo.obtenerTodos();calendario();listado();}catch(RuntimeException e){Toast.makeText(this,"No se pudo cargar la agenda",Toast.LENGTH_LONG).show();android.util.Log.e("AgendaPersonal","Agenda",e);}}
 private void nuevo(Class<? extends Activity> clase){startActivity(new Intent(this,clase).putExtra("nuevo",true).putExtra("fechaInicial",dia.toString()));}
 private void calendario(){if(tareas==null)return;virtuales=com.example.agendapersonal.eventos.SeriesEvento.virtuales(this,mes.atDay(1),mes.atEndOfMonth());((TextView)findViewById(R.id.tituloMes)).setText(mes.format(DateTimeFormatter.ofPattern("MMMM yyyy",new Locale("es"))));GridLayout grid=findViewById(R.id.calendarioGrid);grid.removeAllViews();Set<String>marcados=new HashSet<>();for(Tarea t:tareas){marcados.add(t.getFechaInicio());marcados.add(t.getFechaVencimiento());}for(Evento e:eventos)marcados.add(e.getFecha());for(com.example.agendapersonal.ui.registro.Registro r:virtuales)marcados.add(r.texto("fecha"));for(String nombre:new String[]{"L","M","X","J","V","S","D"})celda(grid,nombre,null,false);int vacias=mes.atDay(1).getDayOfWeek().getValue()-1;for(int i=0;i<vacias;i++)celda(grid,"",null,false);for(int n=1;n<=mes.lengthOfMonth();n++){LocalDate f=mes.atDay(n);celda(grid,String.valueOf(n)+(marcados.contains(f.toString())?"\n•":""),f,f.equals(dia));}}
 private void celda(GridLayout grid,String texto,LocalDate fecha,boolean elegida){TextView v=new TextView(this);v.setText(texto);v.setGravity(android.view.Gravity.CENTER);v.setTextSize(15);v.setTextColor(elegida?android.graphics.Color.WHITE:com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_text));if(elegida)v.setBackground(EstiloApp.fondo(com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_primary),12,android.graphics.Color.TRANSPARENT,this));if(fecha!=null){v.setContentDescription(fecha.toString()+(texto.contains("•")?", con registros":""));v.setFocusable(true);v.setOnClickListener(w->{dia=fecha;calendario();listado();});}GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.height=EstiloApp.dp(this,48);p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);grid.addView(v,p);}
 private void listado(){LinearLayout lista=findViewById(R.id.listaAgenda);lista.removeAllViews();((TextView)findViewById(R.id.tituloDia)).setText(dia.format(DateTimeFormatter.ofPattern("d 'de' MMMM",new Locale("es"))));String fecha=dia.toString();int cantidad=0;
  List<Evento>delDia=new ArrayList<>();for(Evento e:eventos)if(fecha.equals(e.getFecha()))delDia.add(e);delDia.sort(Comparator.comparing(e->e.getHora()==null?"99:99":e.getHora()));
  if(!delDia.isEmpty())etiqueta(lista,"Eventos");for(Evento e:delDia){cantidad++;fila(lista,e.getDescripcion(),e.getHora(),e.getCategoria(),ReglasAgenda.estado(e.getFecha(),e.getEstadoEspecial(),LocalDate.now()),e.isAlarmaActivada(),EventosActivity.class,e.getId());}
  for(com.example.agendapersonal.ui.registro.Registro r:virtuales)if(fecha.equals(r.texto("fecha"))){cantidad++;fila(lista,r.texto("descripcion"),r.get("hora"),r.texto("categoria"),ReglasAgenda.estado(r.texto("fecha"),r.get("estadoEspecial"),LocalDate.now()),Boolean.parseBoolean(r.texto("alarmaActivada")),EventosActivity.class,r.texto("id"));View fila=lista.getChildAt(lista.getChildCount()-1);fila.setOnClickListener(v->startActivity(new Intent(this,EventosActivity.class).putExtra("serieId",r.texto("_serie")).putExtra("ordinal",Long.parseLong(r.texto("_ordinal")))));}
  List<Tarea>delDiaT=new ArrayList<>();for(Tarea t:tareas)if(fecha.equals(t.getFechaInicio())||fecha.equals(t.getFechaVencimiento()))delDiaT.add(t);
  delDiaT.sort(Comparator.comparingInt((Tarea t)->ReglasAgenda.prioridad(t.getPrioridad())).thenComparing(t->t.getFechaVencimiento()==null?"9999-99-99":t.getFechaVencimiento()).thenComparing(t->t.getHoraVencimiento()==null?"99:99":t.getHoraVencimiento()));
  if(!delDiaT.isEmpty())etiqueta(lista,"Tareas");for(Tarea t:delDiaT){cantidad++;boolean inicio=fecha.equals(t.getFechaInicio());String marca=inicio&&fecha.equals(t.getFechaVencimiento())?"Inicio y vencimiento":inicio?"Inicio":"Vencimiento";fila(lista,t.getDescripcion(),inicio?t.getHoraInicio():t.getHoraVencimiento(),t.getCategoria()+" · "+t.getPrioridad()+" · "+marca,ReglasAgenda.estado(t.getFechaVencimiento(),t.getEstadoEspecial(),LocalDate.now()),t.isAlarmaActivada(),TareasActivity.class,t.getId());}
  if(cantidad==0)etiqueta(lista,"No hay actividades para este día");
 }
 private void etiqueta(LinearLayout lista,String texto){TextView v=new TextView(this);v.setText(texto);v.setTextSize(17);v.setTextColor(com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_text));v.setPadding(0,EstiloApp.dp(this,16),0,EstiloApp.dp(this,12));lista.addView(v);}
 private void fila(LinearLayout lista,String descripcion,String hora,String categoria,String estado,boolean alarma,Class<? extends Activity>clase,String id){View v=getLayoutInflater().inflate(R.layout.item_agenda,lista,false);((TextView)v.findViewById(R.id.agendaDescripcion)).setText(descripcion);((TextView)v.findViewById(R.id.agendaDatos)).setText((hora==null||hora.isEmpty()?"Sin hora":hora)+" · "+categoria+"\n"+estado+(alarma?" · Alarma guardada":""));v.setOnClickListener(w->startActivity(new Intent(this,clase).putExtra("registroId",id)));lista.addView(v);}
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putString("mes",mes.toString());b.putString("dia",dia.toString());}
 @Override public void onBackPressed(){if(menu.estaAbierto())menu.cerrar();else super.onBackPressed();}
 @Override protected void onDestroy(){if(tareasRepo!=null)tareasRepo.cerrar();if(eventosRepo!=null)eventosRepo.cerrar();super.onDestroy();}
}
